import numpy as np

def glcm_contrast(image, levels, dx, dy):
    arr = np.asarray(image, dtype=float)
    h, w = arr.shape
    lo, hi = arr.min(), arr.max()
    if hi == lo:
        quantized = np.zeros((h, w), dtype=int)
    else:
        scaled = (arr - lo) / (hi - lo) * levels
        quantized = np.clip(scaled.astype(int), 0, levels - 1)

    P = np.zeros((levels, levels), dtype=float)
    r_lo, r_hi = max(0, -dy), min(h, h - dy)
    c_lo, c_hi = max(0, -dx), min(w, w - dx)
    for r in range(r_lo, r_hi):
        for c in range(c_lo, c_hi):
            i = quantized[r, c]
            j = quantized[r + dy, c + dx]
            P[i, j] += 1.0

    total = P.sum()
    if total == 0:
        return 0.0
    P /= total

    contrast = 0.0
    for i in range(levels):
        for j in range(levels):
            contrast += (i - j) ** 2 * P[i, j]
    return float(contrast)
